#!/usr/bin/env node
// Condense a captured conversation-logs JSONL into a compact, readable timeline.
import { readFileSync } from 'node:fs';

const file = process.argv[2];
const maxChars = Number(process.argv[3] || 300);
const lines = readFileSync(file, 'utf8').split('\n').filter(Boolean);

function trunc(s, n = maxChars) {
  if (typeof s !== 'string') s = JSON.stringify(s);
  s = s.replace(/\s+/g, ' ').trim();
  return s.length > n ? s.slice(0, n) + `…[${s.length}ch]` : s;
}

let prevTs = null;
for (const line of lines) {
  let obj;
  try { obj = JSON.parse(line); } catch { continue; }
  const ts = obj.timestamp || null;
  let gap = '';
  if (ts && prevTs) {
    const d = (new Date(ts) - new Date(prevTs)) / 1000;
    if (d > 5) gap = ` [+${d.toFixed(0)}s]`;
  }
  if (ts) prevTs = ts;

  if (obj.attachment) {
    console.log(`${ts}${gap} ATTACH:${obj.attachment.type} ${trunc(obj.attachment.hookName || obj.attachment.content || '')}`);
    continue;
  }
  const msg = obj.message;
  if (!msg) { continue; }
  const role = msg.role;
  const content = msg.content;
  if (typeof content === 'string') {
    console.log(`${ts}${gap} ${role.toUpperCase()}: ${trunc(content)}`);
    continue;
  }
  if (Array.isArray(content)) {
    for (const block of content) {
      if (block.type === 'text') {
        console.log(`${ts}${gap} ${role.toUpperCase()} text: ${trunc(block.text)}`);
      } else if (block.type === 'tool_use') {
        console.log(`${ts}${gap} ${role.toUpperCase()} tool_use[${block.name}]: ${trunc(block.input)}`);
      } else if (block.type === 'tool_result') {
        const c = Array.isArray(block.content) ? block.content.map(x => x.text || '').join(' ') : block.content;
        console.log(`${ts}${gap} ${role.toUpperCase()} tool_result: ${trunc(c)}`);
      } else if (block.type === 'thinking') {
        console.log(`${ts}${gap} ${role.toUpperCase()} thinking: ${trunc(block.thinking)}`);
      } else {
        console.log(`${ts}${gap} ${role.toUpperCase()} ${block.type}: ${trunc(block)}`);
      }
    }
  }
}

